//! Golden-value checks for the special functions. The reference tables live in
//! `tests/golden/` and are generated by `tools/golden/special_golden.py` from
//! mpmath at 30 significant digits. Each test reports the worst relative error it
//! sees, so a regression shows up as a number, not just a failure.

use tpt_math_prob_core::special::{
    erf, erfc, gamma_p, gamma_q, ln_binomial, ln_gamma, regularized_incomplete_beta,
};

/// Rows of a CSV table, without the header. Blank lines are ignored.
fn rows(text: &str) -> Vec<Vec<f64>> {
    text.lines()
        .skip(1)
        .filter(|l| !l.trim().is_empty())
        .map(|l| {
            l.split(',')
                .map(|cell| cell.trim().parse::<f64>().expect("numeric golden cell"))
                .collect()
        })
        .collect()
}

/// Relative error, falling back to absolute error when the reference is zero.
fn rel_err(got: f64, want: f64) -> f64 {
    if want == 0.0 {
        got.abs()
    } else {
        ((got - want) / want).abs()
    }
}

/// Asserts every case is within `tol`, and reports the worst one.
fn check(name: &str, cases: impl Iterator<Item = (String, f64, f64)>, tol: f64) {
    let mut worst = (0.0_f64, String::new());
    let mut count = 0;
    for (label, got, want) in cases {
        count += 1;
        let err = rel_err(got, want);
        // A NaN error compares as `None`, so it fails the check.
        if matches!(
            err.partial_cmp(&tol),
            None | Some(core::cmp::Ordering::Greater)
        ) {
            panic!("{name} at {label}: got {got:e}, want {want:e} (rel err {err:e}, tol {tol:e})");
        }
        if err > worst.0 {
            worst = (err, label);
        }
    }
    assert!(count > 0, "{name}: empty table");
    eprintln!(
        "{name}: {count} cases, worst relative error {:.2e} at {}",
        worst.0, worst.1
    );
}

#[test]
fn gamma_p_and_q_match_mpmath() {
    let table = rows(include_str!("golden/gamma.csv"));
    let p_cases = table.iter().map(|r| {
        (
            format!("P(a={}, x={})", r[0], r[1]),
            gamma_p(r[0], r[1]),
            r[2],
        )
    });
    check("gamma_p", p_cases, 1e-10);
    let q_cases = table.iter().map(|r| {
        (
            format!("Q(a={}, x={})", r[0], r[1]),
            gamma_q(r[0], r[1]),
            r[3],
        )
    });
    check("gamma_q", q_cases, 1e-10);
}

#[test]
fn erf_and_erfc_match_mpmath() {
    let table = rows(include_str!("golden/erf.csv"));
    check(
        "erf",
        table
            .iter()
            .map(|r| (format!("x={}", r[0]), erf(r[0]), r[1])),
        1e-12,
    );
    check(
        "erfc",
        table
            .iter()
            .map(|r| (format!("x={}", r[0]), erfc(r[0]), r[2])),
        1e-12,
    );
}

#[test]
fn ln_gamma_matches_mpmath() {
    let table = rows(include_str!("golden/loggamma.csv"));
    // lgamma crosses zero near x = 1 and 2, so use the absolute scale there.
    let cases = table.iter().map(|r| {
        let want = r[1];
        let got = ln_gamma(r[0]);
        let scale = want.abs().max(1.0);
        (format!("x={}", r[0]), got / scale, want / scale)
    });
    check("ln_gamma", cases, 1e-12);
}

#[test]
fn regularized_incomplete_beta_matches_mpmath() {
    let table = rows(include_str!("golden/beta_reg.csv"));
    check(
        "regularized_incomplete_beta",
        table.iter().map(|r| {
            (
                format!("I_{}({}, {})", r[2], r[0], r[1]),
                regularized_incomplete_beta(r[0], r[1], r[2]),
                r[3],
            )
        }),
        1e-10,
    );
}

#[test]
fn ln_binomial_matches_mpmath_for_large_n() {
    let table = rows(include_str!("golden/ln_binomial.csv"));
    check(
        "ln_binomial",
        table.iter().map(|r| {
            (
                format!("C({}, {})", r[0], r[1]),
                ln_binomial(r[0] as u64, r[1] as u64),
                r[2],
            )
        }),
        1e-12,
    );
}
